WITH prev_events AS (SELECT *, LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) AS prev_started_at FROM sessions), flagged AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT id, customer_id, device, browser, started_at, country, island_id, CASE WHEN device RLIKE '^(desktop|tablet)$' THEN 'PRIORITY' WHEN device RLIKE '^(mobile)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS device_zone FROM sessionized
